parameters {
  vector[N_models] theta;
  vector<lower=0>[N_items] a;
  vector[N_items] b;
  vector<lower=0, upper=1>[N_items] c;
  vector<lower=0, upper=1>[N_items] d;
  real gamma;
}

model {
  // Priors
  theta ~ std_normal();
  a ~ lognormal(0, 0.5);
  b ~ std_normal();
  c ~ beta(5, 20);
  d ~ beta(20, 5);
